mapper.update:
update biz_order set order_status = #{orderStatus}, pay_status = #{payStatus},
    refund_status = #{refundStatus}, cancel_time = #{cancelTime}, cancel_reason = #{cancelReason}
where id = #{id} and order_status = 1 and pay_status = 1 and refund_status = 0

update biz_order set order_status = #{orderStatus}, pay_status = #{payStatus},
    cancel_time = #{cancelTime}, cancel_reason = #{cancelReason}
where id = #{id} and order_status = 0 and pay_status = 0

mapper.select:

where shop_id = #{shopId}
  and pay_status = 1
  and (
    pickup_token = #{code}
    or order_no = #{code}
    or (pickup_display = #{code} and order_status in (2, 3))
  )
order by
  case
    when pickup_token = #{code} then 1
    when order_no = #{code} then 2
    else 3
  end,
  id desc
limit 1
for update

mapper.update:
update biz_order
set order_status = 2, make_start_time = #{makeStartTime}, update_time = #{makeStartTime}
where id = #{id}
  and shop_id = #{shopId}
  and order_status = 1
  and pay_status = 1

update biz_order
set order_status = 3, complete_make_time = #{scanOutTime}, update_time = #{scanOutTime}
where id = #{id}
  and shop_id = #{shopId}
  and order_status = 2
  and pay_status = 1

update biz_order
set order_status = 4, verify_time = #{completeTime}, update_time = #{completeTime}
where id = #{id}
  and shop_id = #{shopId}
  and order_status = 3
  and pay_status = 1

update biz_order
set order_status = 4, verify_time = #{completeTime}, update_time = #{completeTime}
where id = #{id}
  and order_status in (1, 2, 3)
  and pay_status = 1

mapper.select:

where order_status = 3
  and pay_status = 1
  and complete_make_time is not null
  and complete_make_time <= #{deadline}
  and id > #{minId}
order by id asc limit #{limit}


where order_status in (1, 2, 3)
  and pay_status = 1
  and pickup_date is not null
  and pickup_date < #{cutoffPickupDate}
  and id > #{minId}
order by id asc limit #{limit}
